int irda_sock_recvmsg(struct kiocb *iocb, struct socket *sock,
                      struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = skb->len;
    if (size < copied) {
        copied = size;
        msg->msg_flags |= MSG_TRUNC;
    }

    err = memcpy_to_msg(msg, skb->data, copied);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    kfree_skb(skb);

    if ((sk->sk_shutdown & RCV_SHUTDOWN) &&
        skb_queue_empty(&sk->sk_receive_queue))
        sk->sk_state = IRDA_STATE_CLOSED;

    if (test_bit(IRDA_SKB_STOLEN, &sk->sk_flags))
        clear_bit(IRDA_SKB_STOLEN, &sk->sk_flags);

    if (test_bit(IRDA_FLOW_STOPPED, &sk->sk_flags) &&
        !skb_queue_empty(&sk->sk_receive_queue))
        clear_bit(IRDA_FLOW_STOPPED, &sk->sk_flags);

    return copied;
}

ssize_t irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int len;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    len = skb->len;
    if (size < len) {
        msg->msg_flags |= MSG_TRUNC;
        len = size;
    }

    if (memcpy_to_msg(msg, skb->data, len) < 0) {
        kfree_skb(skb);
        return -EFAULT;
    }

    kfree_skb(skb);

    /* Restart IrTTP flow if stopped and queue has space */
    if ((flags & MSG_OOB) && skb_queue_len(&sk->sk_receive_queue) < IRDA_RECV_QUEUE_LIMIT)
        irtt_flow_on(sk);

    return len;
}

int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int ret = 0;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = min_t(size_t, skb->len, size);
    if (copied < skb->len)
        msg->msg_flags |= MSG_TRUNC;

    ret = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (ret < 0) {
        kfree_skb(skb);
        return ret;
    }

    kfree_skb(skb);

    if ((sk->sk_shutdown & RCV_SHUTDOWN) && skb_queue_empty(&sk->sk_receive_queue))
        msg->msg_flags |= MSG_EOR;

    if (sk->sk_irc_state & IRDA_FLOW_STOPPED &&
        !skb_queue_empty(&sk->sk_receive_queue)) {
        sk->sk_irc_state &= ~IRDA_FLOW_STOPPED;
        irda_start_flow(sk);
    }

    return copied;
}

int irda_sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                      size_t size, int flags)
{
    struct sk_buff *skb;
    int len = 0;

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    len = min(skb->len, size);
    if (skb->len > size)
        msg->msg_flags |= MSG_TRUNC;

    if (copy_from_iter(skb->data, len, &msg->msg_iter) != len) {
        kfree_skb(skb);
        return -EFAULT;
    }

    kfree_skb(skb);

    if ((sock->sk->sk_flow_flags & SK_F_STOP) &&
        skb_queue_len(&sock->sk->sk_receive_queue) > 0)
        sk_clear_flow_stop(sock->sk);

    return len;
}

ssize_t irda_sock_recvmsg(struct kiocb *iocb, struct socket *sock,
                          struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (skb->len > size) {
        msg->msg_flags |= MSG_TRUNC;
        copied = size;
        err = -EINVAL;
    } else {
        copied = skb->len;
    }

    if (memcpy_to_msg(msg, skb->data, copied)) {
        err = -EFAULT;
    }

    kfree_skb(skb);

    if (test_and_clear_bit(IRDA_SOCK_RX_STOPPED, &sk->sk_user_data)) {
        irttp_rx_start(sk);
    }

    return (err) ? err : copied;
}
